    <section class="panel">
      <div class="panel-title"><h2>Latest Agent Brain activity</h2><button type="button" class="panel-link" data-view="brain">Open Agent Brain →</button></div>
      ${recentBrain.length?`<div class="dashboard-brain-grid">${recentBrain.slice(0,8).map(b=>`<button type="button" class="dashboard-brain-card" data-view="brain"><small>${esc(b.phase||'decision')} · ${esc(b.provider_status||'')}</small><strong>${esc(b.route||b.action||'Agent decision')}</strong><p>${esc(b.request_excerpt||b.response_excerpt||'')}</p><span>${esc(b.display_name||b.email||'User')} · ${Number(b.input_tokens||0)+Number(b.output_tokens||0)} tokens</span></button>`).join('')}</div>`:'<div class="empty compact">No Agent Brain entries yet.</div>'}
    </section>

