  async function uploadOne(batch,g,e){const fd=new FormData();fd.append('batch_id',batch);fd.append('track_key',slug(g.title));fd.append('relative_path',e.relativePath||e.file.name);fd.append('file',e.file,e.file.name);return uploadApi('upload.php',fd)}
  async function uploadAndImport(){const template=$('#scanTemplate')?.value,release=$('#scanRelease')?.value.trim()||'Unreleased';if(!template){say('Choose a metadata template first.');return}const bad=app.scanGroups.find(g=>g.isrc&&String(g.isrc).replace(/[^A-Z0-9]/gi,'').length!==12);if(bad){say('Check the ISRC for '+bad.title+'.');return}const btn=$('#importBatch');btn.disabled=true;const progress=$('#uploadProgress span'),status=$('#uploadStatus');const batch='batch-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),total=app.scanGroups.reduce((n,g)=>n+g.files.length,0);let done=0;try{const payload=[];for(const g of app.scanGroups){const ids=new Map();for(const e of g.files){status.textContent='Uploading '+e.file.name+'…';const j=await uploadOne(batch,g,e);ids.set(e.uid,j.upload.id);done++;progress.style.width=((done/total)*85).toFixed(1)+'%'}payload.push({track_key:g.id,title:g.title,duration:g.duration,isrc:g.isrc,upload_ids:[...ids.values()],master_upload_id:ids.get(g.masterUid),preview_upload_id:ids.get(g.previewUid),mood:g.mood,themes:g.themes,energy:g.energy})}status.textContent='Finalizing catalog records…';const j=await api('finalize.php',{batch_id:batch,template_id:template,release,tracks:payload});progress.style.width='100%';status.textContent='Imported '+j.batch.imported.length+' recordings.';await reloadCore();app.scanGroups=[];app.scanEntries=[];say('Import complete. '+j.batch.imported.length+' recordings are now in the Stonefellow catalog.');setTimeout(()=>openView('catalog'),600)}catch(err){status.textContent=err.message;progress.style.width='0%';btn.disabled=false;say('The import stopped: '+err.message)}}

  function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('stonefellow-admin',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('handles'))req.result.createObjectStore('handles')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async function saveHandle(h){const db=await openDB();return new Promise((res,rej)=>{const tx=db.transaction('handles','readwrite');tx.objectStore('handles').put(h,'musicFolder');tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
  async function loadHandle(){const db=await openDB();return new Promise((res,rej)=>{const q=db.transaction('handles').objectStore('handles').get('musicFolder');q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}
  async function rememberFolder(){try{const h=await window.showDirectoryPicker({mode:'read'});try{await saveHandle(h)}catch(_){/* still usable this session */}await scanDirectoryHandle(h)}catch(err){if(err.name!=='AbortError')say('Folder access failed: '+err.message)}}
  async function scanRemembered(){try{const h=await loadHandle();if(!h){say('No remembered folder yet. Use “Attach & remember folder” first.');return}let p=await h.queryPermission?.({mode:'read'});if(p!=='granted')p=await h.requestPermission?.({mode:'read'});if(p!=='granted'){say('Folder permission is required to rescan it.');return}await scanDirectoryHandle(h)}catch(err){say('Could not reopen the folder: '+err.message)}}
  async function scanDirectoryHandle(handle){const entries=[];async function walk(dir,prefix){for await(const [name,h] of dir.entries()){if(entries.length>1500)throw new Error('Folder contains more than 1,500 files. Narrow the folder and scan again.');if(h.kind==='directory')await walk(h,prefix+name+'/');else if(/\.(mp3|wav|wave)$/i.test(name)){const f=await h.getFile();entries.push({file:f,relativePath:prefix+name,uid:crypto.randomUUID?.()||Math.random().toString(36).slice(2)})}}}await walk(handle,'');await scanEntries(entries,handle.name)}

