  function renderReleaseTrackLists(){const cat=$('#releaseCatalogTracks'),ord=$('#releaseTrackOrder');if(!cat||!ord)return;cat.innerHTML=app.catalog.map(t=>`<button type="button" class="picker-track" data-add-track="${esc(t.id)}" ${app.releaseDraftTracks.includes(t.id)?'disabled':''}><span><strong>${esc(t.title)}</strong><small>${esc(t.release||'Unreleased')}</small></span><b>+</b></button>`).join('');ord.innerHTML=app.releaseDraftTracks.length?app.releaseDraftTracks.map((id,i)=>{const t=app.catalog.find(x=>x.id===id);return t?`<div class="ordered-track"><span><b>${String(i+1).padStart(2,'0')}</b> ${esc(t.title)}</span><div><button type="button" data-move-up="${esc(id)}" ${i===0?'disabled':''}>↑</button><button type="button" data-move-down="${esc(id)}" ${i===app.releaseDraftTracks.length-1?'disabled':''}>↓</button><button type="button" data-remove-track="${esc(id)}">×</button></div></div>`:''}).join(''):'<div class="empty compact">No tracks selected.</div>';$$('[data-add-track]',cat).forEach(b=>b.onclick=()=>{app.releaseDraftTracks.push(b.dataset.addTrack);renderReleaseTrackLists()});$$('[data-remove-track]',ord).forEach(b=>b.onclick=()=>{app.releaseDraftTracks=app.releaseDraftTracks.filter(x=>x!==b.dataset.removeTrack);renderReleaseTrackLists()});$$('[data-move-up]',ord).forEach(b=>b.onclick=()=>moveReleaseTrack(b.dataset.moveUp,-1));$$('[data-move-down]',ord).forEach(b=>b.onclick=()=>moveReleaseTrack(b.dataset.moveDown,1))}
