  async function renderOperations(){canvas.innerHTML=head('PRODUCTION HEALTH + AUDIT','Operations','Provider diagnostics, application events, admin audit history, and catalog publishing readiness.',`<button class="secondary" id="refreshOperations" type="button">Refresh</button>`)+`<section class="panel"><div class="empty">Loading operational status…</div></section>`;try{const j=await api('operations.php');app.operations=j;const health=j.health||{},providers=['openai','anthropic','elevenlabs','jev','stripe','email'],validation=j.catalog_validation||{},summary=validation.summary||{},readiness=j.readiness||{},events=j.events||[],audit=j.audit||[];canvas.innerHTML=head('PRODUCTION HEALTH + AUDIT','Operations','Provider diagnostics, application events, admin audit history, and catalog publishing readiness.',`<button class="secondary" id="refreshOperations" type="button">Refresh</button>`)+`<section class="panel"><div class="panel-title"><h2>Provider health</h2><p>Live connectivity tests run only when you click Test</p></div><div class="provider-health-grid">${providers.map(p=>{const h=health[p]||{};return `<div class="provider-health-card"><span class="badge ${h.status==='healthy'?'good':h.status==='error'?'warn':''}">${esc(h.status||'unknown')}</span><strong>${esc(p)}</strong><small>${esc(h.message||'Not tested yet.')}</small><small>${h.checked_at?esc((h.checked_at||'').replace('T',' ').slice(0,19)):'Never tested'}${h.latency_ms?` · ${h.latency_ms}ms`:''}</small><button class="secondary" type="button" data-provider-test="${esc(p)}">Test</button></div>`}).join('')}</div></section><section class="panel"><div class="panel-title"><h2>Runtime readiness</h2><p>Database, storage, backup path and disk</p></div><div class="stats"><div class="stat"><strong>${esc(readiness.database_driver||'—')}</strong><span>Database</span></div><div class="stat"><strong>${readiness.backup_ready?'Ready':'Attention'}</strong><span>Backup path</span></div><div class="stat"><strong>${readiness.app_secret?'Ready':'Missing'}</strong><span>App secret</span></div><div class="stat"><strong>${readiness.disk_free_bytes?Math.round(readiness.disk_free_bytes/1073741824)+' GB':'—'}</strong><span>Disk free</span></div></div>${readiness.storage?`<table class="data-table"><thead><tr><th>Storage</th><th>Exists</th><th>Writable</th></tr></thead><tbody>${Object.entries(readiness.storage).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.exists?'yes':'no'}</td><td>${v.writable?'yes':'no'}</td></tr>`).join('')}</tbody></table>`:''}</section><section class="panel"><div class="panel-title"><h2>Catalog publishing readiness</h2><p>${summary.ready||0}/${summary.tracks||0} ready</p></div><div class="stats"><div class="stat"><strong>${summary.ready||0}</strong><span>Ready</span></div><div class="stat"><strong>${summary.warnings||0}</strong><span>Warnings</span></div><div class="stat"><strong>${summary.errors||0}</strong><span>Errors</span></div><div class="stat"><strong>${summary.tracks||0}</strong><span>Total tracks</span></div></div>${(validation.tracks||[]).filter(t=>t.severity!=='ready').length?`<table class="data-table"><thead><tr><th>Track</th><th>Release</th><th>Severity</th><th>Issues</th></tr></thead><tbody>${validation.tracks.filter(t=>t.severity!=='ready').slice(0,100).map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.release||'')}</td><td><span class="badge ${t.severity==='error'?'warn':''}">${esc(t.severity)}</span></td><td>${esc((t.issues||[]).join(' · '))}</td></tr>`).join('')}</tbody></table>`:'<div class="notice">Catalog is publish-ready.</div>'}</section><section class="panel"><div class="panel-title"><h2>Application events</h2><p>${events.length} recent</p></div>${events.length?`<table class="data-table"><thead><tr><th>Time</th><th>Severity</th><th>Event</th><th>Message</th></tr></thead><tbody>${events.slice(0,60).map(e=>`<tr><td>${esc((e.created_at||'').replace('T',' ').slice(0,19))}</td><td>${esc(e.severity)}</td><td>${esc(e.event_type)}</td><td>${esc(e.message)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No application events.</div>'}</section><section class="panel"><div class="panel-title"><h2>Admin audit</h2><p>${audit.length} recent actions</p></div>${audit.length?`<table class="data-table"><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Entity</th></tr></thead><tbody>${audit.slice(0,60).map(e=>`<tr><td>${esc((e.created_at||'').replace('T',' ').slice(0,19))}</td><td>${esc(e.display_name||e.email||'system')}</td><td>${esc(e.action)}</td><td>${esc([e.entity_type,e.entity_id].filter(Boolean).join(' · '))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No admin audit entries.</div>'}</section>`;$('#refreshOperations').onclick=renderOperations;$$('[data-provider-test]',canvas).forEach(b=>b.onclick=()=>testProvider(b.dataset.providerTest))}catch(e){canvas.innerHTML=head('PRODUCTION HEALTH + AUDIT','Operations','Provider diagnostics, application events, admin audit history, and catalog publishing readiness.')+`<div class="empty">${esc(e.message)}</div>`}}
  async function testProvider(provider){say('Testing '+provider+'…');try{const j=await api('operations.php',{action:'test_provider',provider});say(`${provider}: ${j.result?.status||'done'}${j.result?.latency_ms?' · '+j.result.latency_ms+'ms':''}`);renderOperations()}catch(e){alert(e.message)}}
  function renderSettings(){const php=app.dashboard?.php||{},site=app.site||{};canvas.innerHTML=head('SITE + ADMIN OPERATIONS','Settings','Public-site behavior, launch controls, SEO, browser capabilities, and administrative controls.')+`<section class="panel"><div class="panel-title"><h2>Public site controls</h2><p>Splash, announcement, maintenance and metadata</p></div><form id="siteSettingsForm" class="form-grid"><label class="check-field span3"><input name="splash_enabled" type="checkbox" ${site.splash_enabled?'checked':''}> Show the Stonefellow splash page before the public listening room</label><label class="check-field span3"><input name="fan_community_enabled" type="checkbox" ${site.fan_community_enabled?'checked':''}> Enable public Fan Community feed and posting (CRM, newsletter and fan intelligence remain active when off)</label><label class="check-field span3"><input name="announcement_enabled" type="checkbox" ${site.announcement_enabled?'checked':''}> Show site announcement banner</label><label class="field span3">Announcement<input name="announcement_text" value="${esc(site.announcement_text||'')}" maxlength="180"></label><label class="check-field span3"><input name="maintenance_enabled" type="checkbox" ${site.maintenance_enabled?'checked':''}> Maintenance mode for public visitors (Administrators bypass)</label><label class="field span3">Maintenance message<textarea name="maintenance_message">${esc(site.maintenance_message||'')}</textarea></label><label class="field span3">SEO title<input name="seo_title" value="${esc(site.seo_title||'Stonefellow — Listening Room')}" maxlength="180"></label><label class="field span3">SEO description<textarea name="seo_description">${esc(site.seo_description||'')}</textarea></label><label class="field span3">Instagram URL<input name="social_instagram" value="${esc(site.social_instagram||'')}" placeholder="https://..."></label><label class="field span3">YouTube URL<input name="social_youtube" value="${esc(site.social_youtube||'')}" placeholder="https://..."></label><label class="field span3">Bandcamp URL<input name="social_bandcamp" value="${esc(site.social_bandcamp||'')}" placeholder="https://..."></label><label class="field span3">Spotify URL<input name="social_spotify" value="${esc(site.social_spotify||'')}" placeholder="https://..."></label><label class="field span3">Privacy page<textarea name="privacy_text" rows="8">${esc(site.privacy_text||'')}</textarea></label><label class="field span3">Terms page<textarea name="terms_text" rows="8">${esc(site.terms_text||'')}</textarea></label><div class="actions span3"><button class="primary" type="submit">Save public-site settings</button></div><p id="siteSettingsStatus" class="status-line span3"></p></form></section><section class="panel"><div class="panel-title"><div><h2>Site & artist media</h2><p>Logo, hero/background, artist photos, social-share artwork and app icon.</p></div></div>${window.SFMediaAdmin?.entitySection?.('site','public',{roles:['logo','hero','artist_photo','social_share','app_icon'],publishRoles:['logo','hero','artist_photo','social_share','app_icon']})||'<div class="empty compact">Media module loading…</div>'}</section><section class="panel"><div class="panel-title"><h2>Folder access</h2></div><div class="notice"><strong>Choose folder</strong> works through normal browser directory upload. <strong>Attach & remember folder</strong> uses the File System Access API when supported and stores the permission handle in this browser. Browsers still require you to open Admin and explicitly rescan.</div><p class="status-line">Persistent directory handles: <strong>${'showDirectoryPicker' in window?'supported by this browser':'not supported — use Choose folder'}</strong></p></section><section class="panel"><div class="panel-title"><h2>Server upload limits</h2></div><div class="stats"><div class="stat"><strong>${esc(php.upload_max_filesize||'—')}</strong><span>Single file</span></div><div class="stat"><strong>${esc(php.post_max_size||'—')}</strong><span>POST max</span></div><div class="stat"><strong>${esc(php.max_file_uploads||'—')}</strong><span>PHP file count</span></div><div class="stat"><strong>1</strong><span>Files sent per request</span></div></div></section><section class="panel"><div class="panel-title"><h2>Change my password</h2></div><form id="passwordForm" class="form-grid"><label class="field">Current password<input name="current" type="password" autocomplete="current-password" required></label><label class="field">New password<input name="next" type="password" minlength="10" autocomplete="new-password" required></label><label class="field">Confirm new password<input name="confirm" type="password" minlength="10" autocomplete="new-password" required></label><div class="actions span3"><button class="secondary" type="submit">Change password</button></div><p id="passwordError" class="form-error span3"></p></form></section><section class="panel"><div class="panel-title"><h2>Database upgrade</h2><p>Run ordered schema migrations after uploading a Stonefellow update.</p></div><div class="notice">The database upgrader authenticates an Administrator, creates a pre-upgrade database backup, runs only missing migrations, and verifies the final schema.</div><div class="actions"><a class="secondary" href="../upgrade.php">Open database upgrader</a></div></section><section class="panel"><div class="panel-title"><h2>Admin session</h2></div><div class="actions"><a class="secondary" href="../" target="_blank" rel="noopener">Open public site</a><button class="danger" id="logoutButton" type="button">Log out</button></div></section>`;$('#logoutButton').onclick=()=>{location.href='logout.php'};$('#passwordForm').onsubmit=changePassword;$('#siteSettingsForm').onsubmit=saveSiteSettings;window.SFMediaAdmin?.bindEntityMedia?.('site','public',{roles:['logo','hero','artist_photo','social_share','app_icon'],publishRoles:['logo','hero','artist_photo','social_share','app_icon']})}
  async function saveSiteSettings(e){e.preventDefault();const f=new FormData(e.currentTarget),status=$('#siteSettingsStatus');status.textContent='Saving…';try{const j=await api('settings.php',{action:'save_site',splash_enabled:f.get('splash_enabled')==='on',fan_community_enabled:f.get('fan_community_enabled')==='on',announcement_enabled:f.get('announcement_enabled')==='on',announcement_text:f.get('announcement_text'),maintenance_enabled:f.get('maintenance_enabled')==='on',maintenance_message:f.get('maintenance_message'),seo_title:f.get('seo_title'),seo_description:f.get('seo_description'),social_instagram:f.get('social_instagram'),social_youtube:f.get('social_youtube'),social_bandcamp:f.get('social_bandcamp'),social_spotify:f.get('social_spotify'),privacy_text:f.get('privacy_text'),terms_text:f.get('terms_text')});app.site=j.site||app.site;if(j.csrf)app.csrf=j.csrf;status.textContent='Public-site settings saved. Fan Community is '+(app.site.fan_community_enabled?'on.':'off; CRM remains active.');say(status.textContent)}catch(x){status.textContent=x.message}}
