  function bindAgent(){const form=$('#adminChatForm'),input=$('#adminChatInput'),voice=$('#adminVoiceButton');form.onsubmit=e=>{e.preventDefault();adminCommand(input.value);input.value=''};const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(R){const rec=new R();rec.lang='en-US';rec.interimResults=true;voice.onclick=()=>{try{rec.start();voice.classList.add('active');agent('listening','Listening…')}catch(_){}};rec.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;input.value=t.trim();if(e.results[e.results.length-1].isFinal){voice.classList.remove('active');adminCommand(input.value);input.value=''}};rec.onend=()=>{voice.classList.remove('active');agent('idle')}}else{voice.disabled=true;voice.title='Voice input is not supported by this browser'}}
  function adminCommand(raw){const q=String(raw||'').trim().toLowerCase();if(!q)return;if(/missing.*(art|artwork|cover|poster|media)|unused media|broken media|oversized media|media completeness|attach.*(photo|image|artwork|media)|use.*(photo|image|artwork).*for/.test(q)){openView('media');say('Here is Media Library completeness and usage intelligence. I can show missing artwork, broken or unused assets, and reusable media for releases, shows, campaigns, store products, and the site.');return}if(/media library|media asset|song media|audio upload|artwork upload|photo upload|video upload/.test(q)){openView('media');say('Here is the Media Library. Upload assets once, inspect extracted metadata, then attach them to songs, releases, shows or campaigns.');return}if(/scan|folder|upload|import/.test(q)){openView('uploads');say('Attach or rescan a music folder, choose a metadata template, review the detected recordings, then import.');return}if(/template|songwriting|metadata default/.test(q)){openView('templates');say('Metadata templates hold reusable songwriting, rights, PRO, production and release defaults.');return}if(/missing.*isrc|isrc.*missing/.test(q)){app.missingOnly='isrc';openView('catalog');say('Showing catalog recordings without an ISRC.');return}if(/missing.*writer|writer.*missing/.test(q)){app.missingOnly='writer';openView('catalog');say('Showing catalog recordings missing writer metadata.');return}if(/catalog|song|track/.test(q)){app.missingOnly='';openView('catalog');say('Here is the master catalog. Click a recording to edit track-specific metadata.');return}if(/knowledge|document|image|folder|reference|notes/.test(q)&&!/scan|upload|import/.test(q)){openView('knowledge');say('Here is the agent knowledge base. Create folders, upload documents or images, and explicitly choose what the public agent may use.');return}if(/merch|product|inventory|sku|shirt|poster|store item/.test(q)){openView('products');if(/create|new|add/.test(q))setTimeout(()=>window.SFProductsAdmin?.openProduct?.(''),0);say('Here is Merch + Products. I can help create products, variants, inventory and product media.');return}if(/ticket|rsvp|guest list|check.?in|meet.?greet/.test(q)){openView('ticketing');say('Here is Tickets + VIP for show offers, reservations, guest lists and check-in.');return}if(/membership|vip|member content|exclusive content|early access|presale/.test(q)){openView('membership');say('Here is Membership + VIP. Membership benefits extend the existing subscription packages and billing lifecycle.');return}if(/segment|lifecycle|automation|journey|win.?back|fan nurture|audience rule/.test(q)){openView('automations');say('Here are dynamic fan segments and lifecycle automations. Build reusable audiences, then publish governed journeys with consent-aware actions.');return}if(/campaign|newsletter signup|free download|vip offer|discount offer|fan acquisition|promotion/.test(q)){openView('campaigns');if(/create|new|build/.test(q))setTimeout(()=>window.SFCampaignAdmin?.openEditor?.(0),0);say('Here is the Campaign Builder. Drag triggers, audience gates, offers, messages and conversion actions onto the canvas.');return}if(/release|album|ep|single|publish|artwork|cover/.test(q)){openView('releases');say('Here is the release builder and publishing workflow.');return}if(/support case|customer care|shipment|tracking|return|refund|delivery|fulfillment/.test(q)){openView('fulfillment');say('Here is Fulfillment + Care for shipments, refunds, returns and fan support cases.');return}if(/order|sale/.test(q)){openView('orders');say('Showing direct-sale orders.');return}if(/pod|press|manufactur|vinyl|cassette/.test(q)){openView('pod');say('Showing physical manufacturing handoffs.');return}if(/user|account|member|administrator/.test(q)){openView('users');say('Here are Stonefellow user accounts and administrator roles.');return}if(/billing|invoice|receipt|email verification|password reset|webhook/.test(q)){openView('customer');say('Here are customer lifecycle, transactional email and recurring billing controls.');return}if(/package|plan|subscription|monthly|trial/.test(q)){openView('packages');say('Here are the public monthly packages and free-trial settings.');return}if(/analytics|listen|audience|plays|streams/.test(q)){openView('analytics');say('Here is listening analytics for the overall audience and individual users.');return}if(/health|diagnostic|operations|provider status|audit log/.test(q)){openView('operations');say('Here are provider diagnostics, operational events, audit history and publishing readiness.');return}if(/brain|decision|cognit|route|agent audit/.test(q)){openView('brain');say('Here is the Agent Brain decision ledger. It shows JEV routes, Stonefellow actions, context selection and response evaluations.');return}if(/api key|openai|chatgpt|claude|anthropic|elevenlabs|jev|ai provider|llm|voice provider/.test(q)){openView('ai');say('Here are the server-side AI, JEV cognitive routing and voice provider settings.');return}if(/setting|logout/.test(q)){openView('settings');say('Here are admin and folder-access settings.');return}openView('dashboard');say('I can build campaigns, manage releases and artwork, open the knowledge base, scan a music folder, create metadata templates, find missing ISRCs, or show orders and POD handoffs.')}

  startApp();
